const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const ukBounds = ee.Geometry.Rectangle([-10.0, 49.0, 2.0, 61.0]); // UK bounding box

  // Time periods
  const baselineStart = '2000-02-11';
  const baselineEnd = '2012-02-25';
  const targetStart = '2019-02-11';
  const targetEnd = '2019-02-25';

  // 2. Data Acquisition - MODIS Land Surface Temperature
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
    .select(['LST_Day_1km', 'QC_Day']);

  // Function to process MODIS LST
  function processLST(image) {
    const lst = image.select('LST_Day_1km').multiply(0.02); // Convert to Kelvin
    const qc = image.select('QC_Day');

    // Mask poor quality pixels (QC bits 0-1 = 00 for good quality)
    const qualityMask = qc.bitwiseAnd(3).eq(0);
    return lst.updateMask(qualityMask).subtract(273.15); // Convert to Celsius
  }

  // Get baseline data (2000-2012)
  const baselineCol = modisLST
    .filterDate(baselineStart, baselineEnd)
    .filter(ee.Filter.calendarRange(11, 25, 'day_of_year'))
    .map(processLST);

  // Get target data (2019)
  const targetCol = modisLST
    .filterDate(targetStart, targetEnd)
    .map(processLST);

  // Check collection sizes
  const baselineSize = baselineCol.size().getInfo();
  const targetSize = targetCol.size().getInfo();

  console.log(`Baseline images (2000-2012): ${baselineSize}`);
  console.log(`Target images (2019): ${targetSize}`);

  if (baselineSize === 0 || targetSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate means
  const baselineMean = baselineCol.mean();
  const targetMean = targetCol.mean();

  // Get pixel counts to check for valid data
  const baselineCount = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: ukBounds,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const targetCount = targetMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: ukBounds,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Baseline valid pixels: ${baselineCount}`);
  console.log(`Target valid pixels: ${targetCount}`);

  if (baselineCount === 0 || targetCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean temperatures
  const baselineTemp = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: ukBounds,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const targetTemp = targetMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: ukBounds,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Baseline temp (2000-2012): ${baselineTemp ? baselineTemp.toFixed(2) : 'N/A'}°C`);
  console.log(`Target temp (2019): ${targetTemp ? targetTemp.toFixed(2) : 'N/A'}°C`);

  // Validation & Final Answer
  if (baselineTemp === null || targetTemp === null || 
      isNaN(baselineTemp) || isNaN(targetTemp) ||
      Math.abs(baselineTemp) > 50 || Math.abs(targetTemp) > 50) { // Unreasonable temps
    console.log("<answer>C3</answer>");
  } else if (targetTemp > baselineTemp) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
